const raw = $input.first().json;
const body = raw.body !== undefined ? raw.body : raw;
const dryRun = body.dry_run === true;

const problems = [];

if (typeof body.name !== 'string' || !body.name.trim()) problems.push('name is required');
if (typeof body.phone !== 'string' || !body.phone.trim()) problems.push('phone is required');
if (typeof body.service !== 'string' || !body.service.trim()) problems.push('service is required');

let requestedDate;
if (typeof body.requested_start !== 'string' || isNaN(Date.parse(body.requested_start))) {
  problems.push('requested_start must be a valid ISO 8601 date-time string');
} else {
  requestedDate = new Date(body.requested_start);
}

if (typeof body.duration_min !== 'number' || !(body.duration_min > 0)) {
  problems.push('duration_min must be a positive number');
}

const bh = body.business_hours;
if (!bh || typeof bh.open !== 'string' || typeof bh.close !== 'string' || typeof bh.tz_offset_min !== 'number') {
  problems.push('business_hours with open, close (HH:MM) and tz_offset_min is required');
}

if (body.existing_bookings !== undefined && !Array.isArray(body.existing_bookings)) {
  problems.push('existing_bookings must be an array');
}

if (problems.length) {
  return [{
    json: {
      status: 'invalid',
      errors: problems,
      dry_run: dryRun,
      dispatched: false,
    },
  }];
}

function parseHHMM(s) {
  const [h, m] = s.split(':').map(Number);
  return h * 60 + m;
}
function toLocalShifted(date, tz) {
  return new Date(date.getTime() + tz * 60000);
}
function fromLocalShifted(date, tz) {
  return new Date(date.getTime() - tz * 60000);
}
function localDayOpen(localShifted, openMin) {
  return new Date(Date.UTC(localShifted.getUTCFullYear(), localShifted.getUTCMonth(), localShifted.getUTCDate(), Math.floor(openMin / 60), openMin % 60, 0));
}
function localDayClose(localShifted, closeMin) {
  return new Date(Date.UTC(localShifted.getUTCFullYear(), localShifted.getUTCMonth(), localShifted.getUTCDate(), Math.floor(closeMin / 60), closeMin % 60, 0));
}

const tz = bh.tz_offset_min;
const openMin = parseHHMM(bh.open);
const closeMin = parseHHMM(bh.close);
const duration = body.duration_min;

let bookings = (body.existing_bookings || []).map((b) => ({ ...b, start: new Date(b.start), end: new Date(b.end) }));
if (body.action === 'reschedule' && body.booking_id) {
  bookings = bookings.filter((b) => b.id !== body.booking_id);
}

const reqStart = requestedDate;
const reqEnd = new Date(reqStart.getTime() + duration * 60000);

const startLocal = toLocalShifted(reqStart, tz);
const startLocalMin = startLocal.getUTCHours() * 60 + startLocal.getUTCMinutes();
const endLocalMin = startLocalMin + duration;
const withinHours = startLocalMin >= openMin && endLocalMin <= closeMin;

const overlaps = bookings.some((b) => reqStart < b.end && reqEnd > b.start);
const conflict = !withinHours || overlaps;

if (!conflict) {
  const confirmation_text = `Booked ${body.service} for ${body.name} on ${reqStart.toISOString()} (${duration} min).`;
  return [{
    json: {
      status: 'confirmed',
      slot: { start: reqStart.toISOString(), end: reqEnd.toISOString() },
      confirmation_text,
      dry_run: dryRun,
      dispatched: false,
    },
  }];
}

// Build up to 3 alternative slots in 30-minute steps, same or next business day.
let candidateLocal = toLocalShifted(reqStart, tz);
const totalMin = candidateLocal.getUTCHours() * 60 + candidateLocal.getUTCMinutes();
const remainder = totalMin % 30;
if (remainder !== 0 || candidateLocal.getUTCSeconds() > 0) {
  candidateLocal = new Date(candidateLocal.getTime() + (30 - remainder) * 60000);
}
candidateLocal.setUTCSeconds(0, 0);

let dayOpen = localDayOpen(candidateLocal, openMin);
if (candidateLocal < dayOpen) candidateLocal = dayOpen;

const alternatives = [];
let guard = 0;
while (alternatives.length < 3 && guard < 500) {
  guard++;
  const dClose = localDayClose(candidateLocal, closeMin);
  if (candidateLocal.getTime() + duration * 60000 > dClose.getTime()) {
    const nextDay = new Date(candidateLocal.getTime());
    nextDay.setUTCDate(nextDay.getUTCDate() + 1);
    candidateLocal = localDayOpen(nextDay, openMin);
    continue;
  }
  const slotStartUtc = fromLocalShifted(candidateLocal, tz);
  const slotEndUtc = new Date(slotStartUtc.getTime() + duration * 60000);
  const busy = bookings.some((b) => slotStartUtc < b.end && slotEndUtc > b.start);
  if (!busy) {
    alternatives.push({ start: slotStartUtc.toISOString(), end: slotEndUtc.toISOString() });
  }
  candidateLocal = new Date(candidateLocal.getTime() + 30 * 60000);
}

return [{
  json: {
    status: 'conflict',
    reason: !withinHours ? 'outside_business_hours' : 'overlaps_existing_booking',
    alternatives,
    dry_run: dryRun,
    dispatched: false,
  },
}];

const base = $('Validate & Decide').item.json;
return [{
  json: {
    ...base,
    dispatched: true,
  },
}];
